#!/usr/bin/env bash
# Start the CAD Viewer the way the shipped skill tells a user to, and check it answers.
#
# Every other check asks whether the distribution is correctly ASSEMBLED. bundle.sh --check
# compares generated bytes, check-builds.sh inspects the layout, and the wheel check lists
# package data. None of them RUN it. `npm start` was declared in the runtime's package.json,
# shipped without its launcher, and stayed broken from 0.4.0 to 0.4.18 because no test ever
# executed the one command the skill documents. The client now ships inside cadgen as package
# data, which trades a missing launcher for a glob that can quietly stop matching -- a fresh
# way to ship a viewer that imports fine and serves nothing.
#
# The command below is that command. Keep it identical to the one in
# skills/cad-viewer/SKILL.md; if the doc changes, this changes with it.
set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# shellcheck source=scripts/test/common.sh
. "$SCRIPT_DIR/common.sh"

PORT="${VIEWER_LAUNCH_PORT:-3299}"
HOST="127.0.0.1"

# SKILL.md documents `cadgen viewer`, and `python -m cadgen.viewer` for when cadgen is not on
# PATH. Prefer the console script so this also proves the entry point is wired up.
if command -v cadgen >/dev/null 2>&1; then
  VIEWER_CMD=(cadgen viewer)
else
  VIEWER_CMD=("$PYTHON_BIN" -m cadgen.viewer)
fi

echo "==> CAD Viewer launch smoke test (${VIEWER_CMD[*]})"

# The built client has to resolve before anything else is worth trying: its absence is the
# exact regression this guards, and it surfaces as a served page that is 404 rather than as a
# bad server. Ask cadgen.assets the same way the backend does.
if ! dist="$("$PYTHON_BIN" -c 'from cadgen.assets import viewer_dist_dir; print(viewer_dist_dir())' 2>&1)"; then
  echo "FAIL: the viewer client does not resolve" >&2
  echo "      $dist" >&2
  echo "      Build it with 'npm --prefix viewer run build', or check the viewer package-data" >&2
  echo "      glob in packages/cadgen/pyproject.toml." >&2
  exit 1
fi
echo "    client: $dist"

log="$(mktemp)"
"${VIEWER_CMD[@]}" --host "$HOST" --port "$PORT" > "$log" 2>&1 &
launcher_pid=$!
# Bash reports a killed background job on stderr ("Terminated: 15"), which lands in CI
# directly after the pass line and reads like a failure. Dropping the job from the table
# silences that; the PID stays valid for kill/kill -0 because it is still our child.
disown "$launcher_pid" 2>/dev/null || true

cleanup() {
  kill "$launcher_pid" 2>/dev/null || true
  pkill -P "$launcher_pid" 2>/dev/null || true
  # `cadgen viewer` spawns the backend as a child (cadgen.viewer.server), so killing the
  # launcher alone can leave the port held and fail the next run for an unrelated reason.
  pkill -f "cadgen\.viewer\.server.*--port $PORT" 2>/dev/null || true
}
trap cleanup EXIT

status=""
for _ in $(seq 1 30); do
  status="$(curl -s -o /dev/null -m 3 -w '%{http_code}' "http://$HOST:$PORT/" || true)"
  [ "$status" = "200" ] && break
  if ! kill -0 "$launcher_pid" 2>/dev/null; then
    echo "FAIL: the launcher exited before serving" >&2
    sed 's/^/    /' "$log" >&2
    exit 1
  fi
  sleep 1
done

if [ "$status" != "200" ]; then
  echo "FAIL: no 200 from http://$HOST:$PORT/ (last status: ${status:-none})" >&2
  sed 's/^/    /' "$log" >&2
  exit 1
fi

# The front end alone is not proof: the backend serves a prebuilt bundle, so a live page with
# a dead CAD API still looks fine in a browser until the first model load.
api="$(curl -s -o /dev/null -m 3 -w '%{http_code}' "http://$HOST:$PORT/__cad/server" || true)"
if [ "$api" != "200" ]; then
  echo "FAIL: the page served but /__cad/server returned ${api:-none}" >&2
  sed 's/^/    /' "$log" >&2
  exit 1
fi

echo "    served / and /__cad/server on port $PORT"
echo "==> CAD Viewer launch smoke test passed"
